{"cards": [{"node_code": "N_153c3a45998fbb5a", "definition": "针对港口建设区域的地表形态、地质构造及海底地形进行探测与测绘的技术，旨在获取地形地貌数据以支持工程设计与施工。", "boundary": "本节点聚焦于“地形”与“地貌”的物理形态数据获取。边界在于区分“地形地貌”与“地质”（地质侧重地下岩土性质，本节点侧重地表及水下形态）、“水文”（水文侧重水流运动，本节点侧重静态或动态地形轮廓）。若涉及海底地形测量、岸线变迁分析、地貌特征描述，归入本节点。", "includes": ["港口区域海底地形测量与制图", "岸线、滩涂及近岸地貌特征调查", "地形地貌数据在港口设计中的应用分析"], "excludes": ["地下岩土工程性质试验（归入地质勘测及试验）", "水流速度、波浪要素测量（归入水文勘测）", "气象要素观测（归入气象勘测）"], "sibling_distinctions": [{"other_code": "N_8673dee329c997da", "rule": "本节点侧重地表及水下形态轮廓，兄弟节点侧重地下岩土物理力学性质。"}, {"other_code": "N_981e2de5619b4849", "rule": "本节点侧重地形轮廓与地貌特征，兄弟节点侧重水流、波浪等水文动力要素。"}, {"other_code": "N_449ace8aeb61f320", "rule": "本节点侧重自然地理形态，兄弟节点侧重港口工程控制点、坐标及高程的精密测量。"}], "cross_boundary_rule": "若内容涉及地形测量方法，主挂载本节点；若涉及基于地形的工程布局，可关联港口设计。"}, {"node_code": "N_5ef1bf86e6f46884", "definition": "针对港口所在区域的气象要素（风、温、湿、降水等）进行长期观测、统计分析及特征值确定的技术，为港口设计提供气象依据。", "boundary": "本节点聚焦于“气象”要素的观测与统计。边界在于区分“气象”与“水文”（水文侧重水体状态，本节点侧重大气状态）、“地质”（地质侧重固体地球）。若涉及风向频率、风速分布、气温变化、降水量统计等对港口作业及结构安全有影响的气象数据，归入本节点。", "includes": ["港口区域风、温、湿、降水等气象要素观测", "气象要素的统计分析与极值确定", "气象条件对港口工程的影响评估"], "excludes": ["水流、波浪、潮汐等水文要素测量（归入水文勘测）", "地下岩土性质调查（归入地质勘测及试验）", "大气污染监测（非工程气象范畴）"], "sibling_distinctions": [{"other_code": "N_981e2de5619b4849", "rule": "本节点侧重大气气象要素，兄弟节点侧重水体水文要素。"}, {"other_code": "N_8673dee329c997da", "rule": "本节点侧重大气环境，兄弟节点侧重地下岩土环境。"}], "cross_boundary_rule": "若内容涉及气象观测方法，主挂载本节点；若涉及气象数据在结构设计中的荷载计算，可关联港口设计。"}, {"node_code": "N_449ace8aeb61f320", "definition": "在港口工程区域内建立测量控制网，进行平面位置、高程及变形监测的精密测量技术，为港口施工与运营提供空间基准。", "boundary": "本节点聚焦于“测量”与“控制网”建立。边界在于区分“港区测量”与“地形勘测”（地形勘测侧重自然形态描述，本节点侧重工程控制点与坐标系统）、“地质勘测”（地质侧重物质性质，本节点侧重空间位置）。若涉及港口工程控制点布设、坐标系统转换、施工放样、变形监测等，归入本节点。", "includes": ["港口工程测量控制网布设与计算", "港口施工放样与竣工测量", "港口建筑物变形监测与精度控制"], "excludes": ["自然地形地貌形态描述（归入地形、地貌勘测）", "水文、气象要素观测（归入相应勘测节点）", "港口总体规划布局（归入港口总体规划）"], "sibling_distinctions": [{"other_code": "N_153c3a45998fbb5a", "rule": "本节点侧重工程控制与坐标基准，兄弟节点侧重自然地形形态描述。"}, {"other_code": "N_8673dee329c997da", "rule": "本节点侧重空间位置测量，兄弟节点侧重岩土性质试验。"}], "cross_boundary_rule": "若内容涉及测量方法与控制网，主挂载本节点；若涉及测量数据在结构设计中的应用，可关联港口设计。"}]}
